var R=8.314462618;
function solve(o){
  var p=o.p,v=o.v,n=o.n,t=o.t;
  if(v!=null&&n!=null&&t!=null){ if(v<=0||n<=0||t<=0)return{error:'量须为正'}; p=n*R*t/v; }
  else if(p!=null&&v!=null&&t!=null){ if(p<=0||v<=0||t<=0)return{error:'量须为正'}; n=p*v/(R*t); }
  else if(p!=null&&n!=null&&t!=null){ if(p<=0||n<=0||t<=0)return{error:'量须为正'}; v=n*R*t/p; }
  else if(p!=null&&v!=null&&n!=null){ if(p<=0||v<=0||n<=0)return{error:'量须为正'}; t=p*v/(n*R); }
  else return {error:'需提供三个已知量 (P,V,n,T)'};
  return {p:p,v:v,n:n,t:t};
}
